def profile(**fields):
    return ", ".join(f"{k}={v}" for k, v in fields.items())

print(total(10, 20, 30))
print(total())
print(profile(name="Asha", city="Pune"))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))
print(factorial(1))

